mapper.sql:
 FROM user_student_verification v JOIN sys_user u ON u.id=v.user_id WHERE 1=1 
AND (CASE WHEN v.verification_status='approved' AND v.expire_at<=#{verificationFilter.now} THEN 'expired' ELSE v.verification_status END)=#{verificationFilter.status}
AND v.submitted_at >=#{verificationFilter.from}
AND v.submitted_at <#{verificationFilter.to}


    AND (v.user_id=#{verificationFilter.keyword} OR CONCAT('SV',v.id)=#{verificationFilter.keyword})
    AND (u.nickname LIKE #{verificationFilter.keyword} ESCAPE '!' OR v.school_name LIKE #{verificationFilter.keyword} ESCAPE '!')
